	// MECHANISM-2: Stronger session affinity (0.4 vs 0.35) combined with spread-aware routing keeps cache-warm instances utilized while preventing overload
	// EXPECT-2: cache_warmup_e2e_ms < 4150
	// RESULT-2: REFUTED (actual=4213.0776202)

	// HYPOTHESIS-3: Adding spread-factor term will specifically reduce load_spikes_e2e_ms below 3300 by penalizing instances far above minimum load
	// MECHANISM-3: During spikes, spread-factor detects imbalance and steers traffic away from above-average instances even when all are moderately loaded
	// EXPECT-3: load_spikes_e2e_ms < 3300
	// RESULT-3: REFUTED (actual=3362.7606800000003)

	scores := make(map[string]float64, len(snapshots))
	for i, scorer := range ws.scorers {
		dimScores := scorer(req, snapshots)
		for _, snap := range snapshots {
			s := dimScores[snap.ID]
			if s < 0 { s = 0 }
			if s > 1 { s = 1 }
			scores[snap.ID] += s * ws.weights[i]
		}
	}

	totalLoad := 0
	maxLoad := 0
	minLoad := 1 << 30
	for _, snap := range snapshots {
		el := snap.EffectiveLoad()
		totalLoad += el
		if el > maxLoad { maxLoad = el }
		if el < minLoad { minLoad = el }
	}
	avgLoad := float64(totalLoad) / float64(len(snapshots))
	loadPressure := avgLoad / (avgLoad + 3.0)
	loadSpread := float64(maxLoad - minLoad)
	spreadFactor := loadSpread / (loadSpread + 4.0)

	isSession := req.SessionID != ""
	inputLen := len(req.InputTokens)
	isLargeInput := inputLen > 512

	loadWeight := 0.45
	if req.SLOClass == "realtime" {
		loadWeight = 0.55
	} else if req.SLOClass == "batch" {
		loadWeight = 0.30
	}

	for _, snap := range snapshots {
		el := float64(snap.EffectiveLoad())

		// Quadratic + cubic load penalty (proven in Program 1)
		if maxLoad > 0 {
			lr := el / float64(maxLoad)
			scores[snap.ID] -= loadPressure * lr * lr * loadWeight
			scores[snap.ID] -= loadPressure * lr * lr * lr * 0.1
		}

		// Spread-aware penalty: penalize instances above minimum (proven in Program 1)
		if loadSpread > 0 {
			aboveMin := (el - float64(minLoad)) / (loadSpread + 1.0)
			scores[snap.ID] -= spreadFactor * aboveMin * 0.15
		}

