		cacheBonus := snap.CacheHitRate * 0.2
		if isSession {
			cacheBonus = snap.CacheHitRate * 0.4
		} else if isLargeInput {
			cacheBonus = snap.CacheHitRate * 0.25
		}
		scores[snap.ID] += cacheBonus

