		if snap.QueueDepth > 0 {
			qPenalty := float64(snap.QueueDepth) / (float64(snap.QueueDepth) + 6.0)
			scores[snap.ID] -= qPenalty * 0.15
		}
	}

	bestScore := -1e9
	bestIdx := 0
	for i, snap := range snapshots {
		if scores[snap.ID] > bestScore {
			bestScore = scores[snap.ID]
			bestIdx = i
		}
	}
